const listUpcomingBillsByUser = `-- name: ListUpcomingBillsByUser :many
SELECT
  id, user_id, title, category, amount, due_date, frequency,
  is_paid, auto_pay, icon_key, icon_color_hex, icon_bg_color_hex,
  paid_at, created_at, updated_at
FROM bills
WHERE user_id = $1
  AND is_paid = FALSE
ORDER BY due_date ASC NULLS LAST, created_at ASC
`

func (q *Queries) ListUpcomingBillsByUser(ctx context.Context, userID uuid.UUID) ([]Bill, error) {
	rows, err := q.db.Query(ctx, listUpcomingBillsByUser, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Bill{}
	for rows.Next() {
		var i Bill
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.Title,
			&i.Category,
			&i.Amount,
			&i.DueDate,
			&i.Frequency,
			&i.IsPaid,
			&i.AutoPay,
			&i.IconKey,
			&i.IconColorHex,
			&i.IconBgColorHex,
			&i.PaidAt,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
